export type ContactDetails = { name: string; email: string; company: string; phone: string; subject: string; message: string };

const supportEmail = "support@Shahvex.com";
const supportPhone = "+92 302 9333326";
const escapeHtml = (value: string) => value.replace(/[&<>'"]/g, character => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[character] || character);

function frame(content: string, preheader: string) {
  const siteUrl = (process.env.NEXT_PUBLIC_SITE_URL || "https://www.Shahvex.com").replace(/\/$/, "");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="x-apple-disable-message-reformatting"><title>Shahvex</title><style>
body{margin:0!important;padding:0!important;background:#faf2eb;color:#3f3730;font-family:Arial,Helvetica,sans-serif;-webkit-text-size-adjust:100%}table{border-collapse:collapse}img{border:0;display:block}.card{width:100%;max-width:600px}.mobile-pad{padding-left:32px!important;padding-right:32px!important}
@media only screen and (max-width:620px){.shell{padding:12px 7px!important}.card{border-radius:14px!important}.mobile-pad{padding-left:19px!important;padding-right:19px!important}.hero-title{font-size:27px!important;line-height:1.18!important}.button{display:block!important;text-align:center!important}.detail-row td{display:block!important;width:auto!important;text-align:left!important;padding:10px 16px!important}.detail-row td+td{padding-top:0!important}.footer-link{display:block!important;margin:6px 0!important}.footer-dot{display:none!important}}
</style></head><body><div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent">${escapeHtml(preheader)}</div><table class="shell" role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;background:#faf2eb;padding:28px 12px"><tr><td align="center"><table class="card" role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;overflow:hidden;border:1px solid #efe7e0;border-radius:20px;background:#fff;box-shadow:0 18px 50px rgba(232, 82, 10,.10)"><tr><td class="mobile-pad" style="padding:22px 32px;border-bottom:1px solid #f6eee7;background:#fff"><a href="${siteUrl}" style="text-decoration:none"><img src="cid:shahvex-logo@shahvex" width="154" alt="Shahvex" style="width:154px;max-width:100%;height:auto"></a></td></tr>${content}<tr><td class="mobile-pad" style="padding:22px 32px;background:#302821;color:#c4bcb5;font-size:11px;line-height:1.7"><strong style="display:block;margin-bottom:5px;color:#fff;font-size:12px">Shahvex</strong>Intelligent voice operations for connected teams.<br><a class="footer-link" href="mailto:${supportEmail}" style="color:#f3ebe4;text-decoration:none">${supportEmail}</a><span class="footer-dot"> &nbsp;·&nbsp; </span><a class="footer-link" href="tel:+923029333326" style="color:#f3ebe4;text-decoration:none">${supportPhone}</a></td></tr></table></td></tr></table></body></html>`;
}

export function contactTeamEmail(details: ContactDetails) {
  const safe = Object.fromEntries(Object.entries(details).map(([key, value]) => [key, escapeHtml(value)])) as Record<keyof ContactDetails, string>;
  const messageHtml = safe.message.replace(/\r?\n/g, "<br>");
  const text = `New Shahvex website enquiry\n\nName: ${details.name}\nEmail: ${details.email}\nCompany: ${details.company || "Not provided"}\nPhone: ${details.phone || "Not provided"}\nEnquiry: ${details.subject}\n\nMessage:\n${details.message}`;
  const html = frame(`<tr><td class="mobile-pad" style="padding:34px 32px 14px;background:linear-gradient(135deg,#fff9f2,#fff)"><span style="display:inline-block;padding:7px 11px;border-radius:999px;background:#fbf3ec;color:#e96016;font-size:10px;font-weight:800;letter-spacing:.6px">NEW WEBSITE ENQUIRY</span><h1 class="hero-title" style="margin:18px 0 9px;color:#3c342d;font-size:30px;line-height:1.2;letter-spacing:-.8px">A new conversation is waiting.</h1><p style="margin:0;color:#888079;font-size:14px;line-height:1.7">${safe.name} contacted Shahvex about <strong style="color:#615952">${safe.subject}</strong>.</p></td></tr><tr><td class="mobile-pad" style="padding:20px 32px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;overflow:hidden;border:1px solid #f3ebe4;border-radius:14px;background:#fffbf4"><tr class="detail-row"><td style="padding:14px 17px;border-bottom:1px solid #f5ede6;color:#a09891;font-size:11px">Name</td><td align="right" style="padding:14px 17px;border-bottom:1px solid #f5ede6;color:#443c35;font-size:12px;font-weight:800">${safe.name}</td></tr><tr class="detail-row"><td style="padding:14px 17px;border-bottom:1px solid #f5ede6;color:#a09891;font-size:11px">Email</td><td align="right" style="padding:14px 17px;border-bottom:1px solid #f5ede6;font-size:12px"><a href="mailto:${safe.email}" style="color:#e96016;text-decoration:none;font-weight:800">${safe.email}</a></td></tr><tr class="detail-row"><td style="padding:14px 17px;border-bottom:1px solid #f5ede6;color:#a09891;font-size:11px">Company</td><td align="right" style="padding:14px 17px;border-bottom:1px solid #f5ede6;color:#443c35;font-size:12px;font-weight:800">${safe.company || "Not provided"}</td></tr><tr class="detail-row"><td style="padding:14px 17px;color:#a09891;font-size:11px">Phone</td><td align="right" style="padding:14px 17px;color:#443c35;font-size:12px;font-weight:800">${safe.phone || "Not provided"}</td></tr></table></td></tr><tr><td class="mobile-pad" style="padding:4px 32px 30px"><p style="margin:0 0 8px;color:#938b84;font-size:10px;font-weight:800;letter-spacing:.5px">MESSAGE</p><div style="padding:17px;border-left:3px solid #e96016;border-radius:4px 12px 12px 4px;background:#fff8f1;color:#615952;font-size:13px;line-height:1.7">${messageHtml}</div><a class="button" href="mailto:${safe.email}" style="display:inline-block;margin-top:20px;padding:13px 20px;border-radius:9px;background:#e96016;color:#fff;font-size:12px;font-weight:800;text-decoration:none">Reply to ${safe.name}</a></td></tr>`, `New ${details.subject} enquiry from ${details.name}`);
  return { subject: `[Shahvex Contact] ${details.subject} — ${details.name}`, text, html };
}

export function contactConfirmationEmail(details: ContactDetails) {
  const safeName = escapeHtml(details.name);
  const safeSubject = escapeHtml(details.subject);
  const siteUrl = (process.env.NEXT_PUBLIC_SITE_URL || "https://www.Shahvex.com").replace(/\/$/, "");
  const text = `Hi ${details.name},\n\nThanks for contacting Shahvex about ${details.subject}. We have received your message and our team will get back to you soon.\n\nNeed to add anything? Reply to this email or contact us at ${supportEmail} / ${supportPhone}.\n\nShahvex`;
  const html = frame(`<tr><td class="mobile-pad" style="padding:38px 32px 14px;background:linear-gradient(145deg,#fff7f0,#fff 68%)"><div style="display:inline-block;width:48px;height:48px;border-radius:15px;background:#e96016;color:#fff;font-size:25px;font-weight:800;line-height:48px;text-align:center;box-shadow:0 10px 24px rgba(232, 82, 10,.28)">✓</div><p style="margin:22px 0 8px;color:#e96016;font-size:10px;font-weight:800;letter-spacing:.7px">MESSAGE RECEIVED</p><h1 class="hero-title" style="margin:0 0 12px;color:#3c342d;font-size:31px;line-height:1.18;letter-spacing:-.9px">Thanks, ${safeName}. We&apos;re on it.</h1><p style="margin:0;color:#877f78;font-size:14px;line-height:1.75">Your message has reached the Shahvex team. A real person will review it and respond as soon as possible.</p></td></tr><tr><td class="mobile-pad" style="padding:22px 32px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border:1px solid #f3ebe4;border-radius:14px;background:#fffaf3"><tr><td style="padding:19px"><span style="display:block;margin-bottom:6px;color:#a09891;font-size:10px;font-weight:800;letter-spacing:.5px">YOUR ENQUIRY</span><strong style="color:#504841;font-size:14px">${safeSubject}</strong></td></tr></table></td></tr><tr><td class="mobile-pad" style="padding:2px 32px 34px"><h2 style="margin:0 0 8px;color:#463e37;font-size:16px">What happens next?</h2><p style="margin:0 0 20px;color:#908881;font-size:13px;line-height:1.7">We&apos;ll review your goals and contact you using the details you provided. If there&apos;s anything else we should know, simply reply to this email.</p><a class="button" href="${siteUrl}" style="display:inline-block;padding:13px 20px;border-radius:9px;background:#e96016;color:#fff;font-size:12px;font-weight:800;text-decoration:none">Explore Shahvex</a></td></tr>`, `Thanks ${details.name} — we received your message`);
  return { subject: "We received your message | Shahvex", text, html };
}
